declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/operational_writes.php';
$action=(string)($_POST['accion']??'');$permissions=['parada'=>'VIAJES_PARADAS','asignar'=>'VIAJES_ASIGNAR','iniciar'=>'VIAJES_INICIAR','finalizar'=>'VIAJES_FINALIZAR','cancelar'=>'VIAJES_CANCELAR'];if(!isset($permissions[$action])){operation_error('Acción no disponible.',404);}require_operation_post($permissions[$action]);try{$id=operation_id($_POST['viaje_id']??null);if($action==='parada'){$location=operation_id($_POST['ubicacion_id']??null);$order=operation_id($_POST['orden']??null);$type=strtoupper((string)($_POST['tipo_parada']??''));if(!in_array($type,['RECOGIDA','ENTREGA','MIXTA','INTERMEDIA'],true)){throw new InvalidArgumentException('Selecciona un tipo de parada válido.');}$sql='DECLARE @parada_id INT; EXEC dbo.sp_agregar_parada @viaje_id=?,@ubicacion_id=?,@orden=?,@tipo_parada=?,@parada_id=@parada_id OUTPUT;';$params=[$id,$location,$order,$type];$success='Parada agregada correctamente.';}elseif($action==='asignar'){$solicitud=operation_id($_POST['solicitud_id']??null);$pickup=operation_id($_POST['parada_recogida_id']??null);$delivery=operation_id($_POST['parada_entrega_id']??null);if($pickup===$delivery){throw new InvalidArgumentException('Las paradas de recogida y entrega deben ser distintas.');}$sql='DECLARE @viaje_solicitud_id INT; EXEC dbo.sp_asignar_solicitud_viaje @viaje_id=?,@solicitud_id=?,@parada_recogida_id=?,@parada_entrega_id=?,@viaje_solicitud_id=@viaje_solicitud_id OUTPUT;';$params=[$id,$solicitud,$pickup,$delivery];$success='Solicitud asignada correctamente.';}elseif($action==='cancelar'){$motivo=operation_text($_POST['motivo']??null,500,false);$sql='EXEC dbo.sp_cancelar_viaje @viaje_id=?,@motivo=?;';$params=[$id,$motivo];$success='Viaje cancelado correctamente y recursos liberados.';}else{$sql=$action==='iniciar'?'EXEC dbo.sp_iniciar_viaje @viaje_id=?;':'EXEC dbo.sp_finalizar_viaje @viaje_id=?;';$params=[$id];$success=$action==='iniciar'?'Viaje iniciado correctamente.':'Viaje finalizado correctamente.';}}catch(InvalidArgumentException $exception){operation_error($exception->getMessage());}try{$stmt=db()->prepare($sql);$stmt->execute($params);$stmt->closeCursor();}catch(PDOException $exception){operation_sql_error($exception,[50307=>'El viaje ya no está en planificación.',50309=>'El viaje no existe o ya inició.',50310=>'La solicitud no está disponible.',50311=>'La solicitud ya está asignada a otro viaje.',50312=>'Las paradas no corresponden a la solicitud.',50313=>'La capacidad de peso es insuficiente.',50314=>'La capacidad de volumen es insuficiente.',50315=>'La solicitud no tiene mercancías.',50317=>'El viaje ya no está planificado.',50318=>'No se puede iniciar un viaje sin solicitudes.',50326=>'El viaje ya no está en curso.',50327=>'Aún hay entregas pendientes.',50328=>'No tiene permiso para cancelar viajes.',50329=>'El viaje especificado no existe.',50330=>'Solo se pueden cancelar viajes en estado PLANIFICADO.']);}operation_success($success,'viajeActualizado','/viajes/detalle.php?id='.$id);
